WITH remaining_keys AS (SELECT id, order_id FROM order_items EXCEPT ALL SELECT id, order_id FROM order_items WHERE order_id = 35), verified AS (SELECT s.* FROM order_items s INNER JOIN remaining_keys k ON s.id = k.id AND s.order_id = k.order_id) SELECT product_id, CASE WHEN quantity >= 7 THEN 'LARGE' ELSE 'SMALL' END AS quantity_tier, MIN(unit_price) AS min_unit_price, COUNT(*) AS event_count, STDDEV_SAMP(quantity) AS quantity_stddev FROM verified GROUP BY product_id, CASE WHEN quantity >= 7 THEN 'LARGE' ELSE 'SMALL' END;
